var cases=0;var failures=0;var assertions=0;
void Check(bool value,string why){assertions++;if(!value)throw new Exception(why);}
void Near(float value,float expected,string why)=>Check(Math.Abs(value-expected)<.0001f,$"{why}: {value} != {expected}");
void Run(string name,Action body){cases++;try{BackpackRuntime.States.Clear();BackpackNative.Uses.Clear();BackpackNative.ItemUses.Clear();Time.time=100;body();Console.WriteLine("PASS "+name);}catch(Exception ex){failures++;Console.WriteLine("FAIL "+name+": "+(ex.InnerException??ex).Message);}}
MethodInfo? Hook(Type t,string name)=>t.GetMethod(name,BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic);
var patchTypes=typeof(BackpackNative).Assembly.GetTypes().Where(t=>t.GetCustomAttribute<HarmonyPatch>() is {Type:var target,Name:"Consume"}&&target==typeof(Stamina)).OrderBy(t=>t.FullName,StringComparer.Ordinal).ToArray();
void Consume(Stamina st,Physical.EConsumptionType type,float cost=10){
 var snapshots=new Dictionary<Type,object?>();Exception? error=null;var consumption=new Physical.Consumption{ConsumptionType=type,Delta=cost};
 object?[] Arguments(MethodInfo method,Type owner)=>method.GetParameters().Select(p=>p.Name switch{"__instance"=>(object)st,"consumption"=>consumption,"__state"=>snapshots.GetValueOrDefault(owner),"__exception"=>error,_=>throw new Exception(p.Name)}).ToArray();
 try{foreach(var t in patchTypes){var prefix=Hook(t,"Prefix");if(prefix==null)continue;var args=Arguments(prefix,t);prefix.Invoke(null,args);var ix=Array.FindIndex(prefix.GetParameters(),p=>p.Name=="__state");if(ix>=0)snapshots[t]=args[ix];}st.Consume(consumption);foreach(var t in patchTypes){var post=Hook(t,"Postfix");if(post!=null)post.Invoke(null,Arguments(post,t));}}
 catch(Exception e){error=e.InnerException??e;}
 finally{foreach(var t in patchTypes){var final=Hook(t,"Finalizer");if(final!=null)error=(Exception?)final.Invoke(null,Arguments(final,t));}}
 if(error!=null)throw error;
}
(Player P,BackpackRuntime.State Bag,Stamina St) MakeStamina(){var p=new Player();var s=new BackpackRuntime.State{Player=p};BackpackRuntime.States[p]=s;return(p,s,p.Physical.Stamina);}
Run("Exactly one EFB owner scopes native Consume",()=>Check(patchTypes.Count(t=>Hook(t,"Finalizer")!=null)==1,"two independently restoring scopes must not coexist"));
Run("Repeated Harness jumps never compound and never alter recovery",()=>{var(p,b,st)=MakeStamina();for(int i=0;i<3;i++){b.Record.Traversal="sprint";b.Record.LastTraversal=Time.time;var before=st.Current;Consume(st,Physical.EConsumptionType.Jump);Near(before-st.Current,8,"one 20% refund");Near(st.Multiplier,1,"shared multiplier restored");Near(st.Recovery(1),2,"restoration remains native");}var current=st.Current;Consume(st,Physical.EConsumptionType.Jump);Near(current-st.Current,10,"unqualified jump normal");});
Run("Removing the bag does not leave a discount",()=>{var(p,b,st)=MakeStamina();b.Record.Traversal="sprint";b.Record.LastTraversal=Time.time;Consume(st,Physical.EConsumptionType.Jump);BackpackRuntime.States.Remove(p);var before=st.Current;Consume(st,Physical.EConsumptionType.Jump);Near(before-st.Current,10,"removed bag");});
Run("Melee and Harness combine exactly once",()=>{var(p,b,st)=MakeStamina();p.Melee=new(){JumpStaminaMultiplier=.5f};b.Record.Traversal="sprint";b.Record.LastTraversal=Time.time;Consume(st,Physical.EConsumptionType.Jump);Near(st.Current,96,"half cost plus 20% refund");Near(st.Multiplier,1,"restoration");Consume(st,Physical.EConsumptionType.Jump);Near(st.Current,91,"melee-only next jump");});
foreach(var type in new[]{Physical.EConsumptionType.VaultLegs,Physical.EConsumptionType.ClimbLegs})Run(type+" composes with melee without leaking",()=>{var(p,b,st)=MakeStamina();p.Melee=new(){VaultLegStaminaMultiplier=.75f};b.Record.Traversal="sprint";b.Record.LastTraversal=99;Consume(st,type);Near(st.Current,94,"correct combined cost");Near(st.Multiplier,1,"restored");Check(b.Record.Traversal=="vault","paid action recorded without leaving a second-action refund");});
Run("Original non-unit native multiplier is restored",()=>{var(p,b,st)=MakeStamina();st.Multiplier=1.5f;b.Record.Traversal="sprint";b.Record.LastTraversal=Time.time;Consume(st,Physical.EConsumptionType.Jump);Near(st.Current,88,"native factor retained");Near(st.Multiplier,1.5f,"original restored");});
Run("Native exceptions restore the shared multiplier",()=>{var(p,b,st)=MakeStamina();st.Fail=true;b.Record.Traversal="sprint";b.Record.LastTraversal=Time.time;try{Consume(st,Physical.EConsumptionType.Jump);Check(false,"exception should propagate");}catch(InvalidOperationException){}Near(st.Multiplier,1,"exception cleanup");});
Run("Reentrant native consumption restores its outer scope",()=>{var(p,b,st)=MakeStamina();p.Melee=new(){JumpStaminaMultiplier=.5f};st.Reenter=true;st.Nested=()=>Consume(st,Physical.EConsumptionType.Jump);b.Record.Traversal="sprint";b.Record.LastTraversal=Time.time;Consume(st,Physical.EConsumptionType.Jump);Near(st.Multiplier,1,"nested restore");});
Run("Free and unrelated actions receive no phantom refund",()=>{var(p,b,st)=MakeStamina();b.Record.Traversal="sprint";b.Record.LastTraversal=Time.time;Consume(st,Physical.EConsumptionType.Jump,0);Near(st.Current,100,"free jump remains free");Near(st.Multiplier,1,"free action restore");Consume(st,Physical.EConsumptionType.Aim);Near(st.Current,90,"unrelated action unchanged");});

(Player P,BackpackRuntime.State Bag,MedEffect Effect) Medical(string key,bool food=false,bool source=true){
 var p=new Player();var bag=new BackpackRuntime.State{Player=p,Key=key};BackpackRuntime.States[p]=bag;
 var item=new Item();if(food)item.Components[typeof(FoodDrinkComponent)]=new FoodDrinkComponent();else item.Components[typeof(MedKitComponent)]=new MedKitComponent{Item=item};if(source)bag.Bag.Children.Add(item);
 var effect=new MedEffect{HealthController=p.ActiveHealthController,MedItem=item};return(p,bag,effect);
}
BackpackRuntime.State Swap(Player p,string key)=>BackpackRuntime.States[p]=new(){Player=p,Key=key};
void TreatmentSetup(Player p){p.ActiveHealthController.Effects.Add(new HeavyBleeding());p.ActiveHealthController.Effects.Add(new LightBleeding());}
void FinishTreatment(Player p,MedEffect e){foreach(var h in p.ActiveHealthController.Effects.OfType<HeavyBleeding>())h.Existing=false;p.ActiveHealthController.Health[EBodyPart.Chest].Current+=5;var food=Native.Component<FoodDrinkComponent>(e.MedItem);if(food!=null)food.HpPercent=0;}
bool Reward(Player p,BackpackRuntime.State b,string key)=>key switch{"BP18-2"=>!p.ActiveHealthController.Effects.OfType<LightBleeding>().Single().Existing,"BP23-3"=>b.Record.Active("bleed:Chest"),"BP29-2"=>p.BonusHealing>0,"BP34-2"=>p.LegRestored>0,"BP36-1"=>p.ExtraHealing>0,_=>throw new Exception(key)};
foreach(var key in new[]{"BP18-2","BP23-3","BP29-2","BP34-2","BP36-1"})foreach(var scenario in new[]{"same bag","other Legendary bag","different copy","item outside bag"})Run(key+" completion: "+scenario,()=>{
 bool food=key is "BP29-2" or "BP34-2";var(p,b,e)=Medical(scenario=="other Legendary bag"?"BP01-3":key,food,scenario!="item outside bag");TreatmentSetup(p);BackpackNative.Begin(e);
 var current=scenario is "other Legendary bag" or "different copy"?Swap(p,key):b;current.Record.LastDrink=100;FinishTreatment(p,e);BackpackNative.End(e);
 Check(Reward(p,current,key)==(scenario=="same bag"),"only the actual source bag qualifies");Check(BackpackNative.Uses.Count==0&&BackpackNative.ItemUses.Count==0,"use snapshots cleared");
 if(key=="BP36-1")Near(Native.Component<MedKitComponent>(e.MedItem)!.HpResource,scenario=="same bag"?90:100,"extra healing consumes resources only for valid source");
});
Run("Fully consumed item still qualifies by captured source ID",()=>{var(p,b,e)=Medical("BP34-2",true);BackpackNative.Begin(e);b.Bag.Children.Clear();FinishTreatment(p,e);BackpackNative.End(e);Near(p.LegRestored,.3f,"consumed item no longer needs a live inventory address");});
Run("Interrupted treatment grants no completion bonus",()=>{var(p,b,e)=Medical("BP36-1");BackpackNative.Begin(e);FinishTreatment(p,e);e._interrupted=true;BackpackNative.End(e);Near(p.ExtraHealing,0,"no interrupted reward");Check(BackpackNative.Uses.Count==0,"cancel snapshot cleared");});
Run("Removing the backpack before completion grants no bonus",()=>{var(p,b,e)=Medical("BP36-1");BackpackNative.Begin(e);BackpackRuntime.States.Remove(p);FinishTreatment(p,e);BackpackNative.End(e);Near(p.ExtraHealing,0,"no unworn completion");});
Run("Starting without EFB cannot adopt a later bag's source bonus",()=>{var(p,b,e)=Medical("BP36-1");BackpackRuntime.States.Remove(p);Check(BackpackNative.Begin(e)==null,"not tracked without EFB");Swap(p,"BP36-1");FinishTreatment(p,e);BackpackNative.End(e);Near(p.ExtraHealing,0,"no invented provenance");});

float InvokeValue(string patch,ActiveHealthController h,float value){var t=typeof(BackpackNative).Assembly.GetTypes().Single(t=>t.Name==patch);object?[] a=[h,value];var effect=BackpackNative.Uses.FirstOrDefault(pair=>pair.Value.Player==h.Player).Key;var previous=effect is null?null:BackpackMedicalRestoration.Enter(effect,false);try{Hook(t,"Prefix")!.Invoke(null,a);return(float)a[1]!;}finally{if(effect is not null)BackpackMedicalRestoration.Exit(previous);}}
foreach(var patch in new[]{"BackpackSurgeryPatch","BackpackEnergyPatch","BackpackHydrationPatch"})foreach(var scenario in new[]{"same bag","other Legendary bag","different copy","item outside bag"})Run(patch+": "+scenario,()=>{
 var surgery=patch=="BackpackSurgeryPatch";var key=surgery?"BP23-2":"BP06-1";var(p,b,e)=Medical(scenario=="other Legendary bag"?"BP01-3":key,!surgery,scenario!="item outside bag");BackpackNative.Begin(e);if(scenario is "other Legendary bag" or "different copy")Swap(p,key);
 Near(InvokeValue(patch,p.ActiveHealthController,surgery ? .5f : 10),scenario=="same bag" ? (surgery ? .875f : 15) : (surgery ? .5f : 10),"only source bag bonus applied");
});
Run("Medical source snapshots cannot cross players",()=>{var(p,b,e)=Medical("BP06-1",true);BackpackNative.Begin(e);var other=new Player();BackpackRuntime.States[other]=new(){Player=other,Key="BP06-1",Bag=b.Bag};Near(InvokeValue("BackpackEnergyPatch",other.ActiveHealthController,10),10,"wrong actor rejected");});

var foliage=typeof(BackpackNative).Assembly.GetTypes().Single(t=>t.Name=="BackpackFoliageSoundPatch");
var transpiler=Hook(foliage,"Transpiler");
List<CodeInstruction> NativeInstructions(){var ops=typeof(OpCodes).GetFields().Where(f=>f.FieldType==typeof(OpCode)).Select(f=>(OpCode)f.GetValue(null)!).ToDictionary(op=>op.Name!);var data=JsonSerializer.Deserialize<List<NativeInstruction>>(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"foliage-native-il.json")))!;return data.Select(x=>new CodeInstruction(ops[x.opcode],x.owner=="EFT.Interactive.TreeInteractive"&&x.name=="_lastVolume"?AccessTools.Field(typeof(TreeInteractive),"_lastVolume"):null)).ToList();}
Run("Native foliage IL has one final volume insertion and retains all original instructions",()=>{
 Check(transpiler!=null,"final-volume transpiler installed");var input=NativeInstructions();input[0].labels.Add("branch");var output=((IEnumerable<CodeInstruction>)transpiler!.Invoke(null,[input])!).ToList();Check(output.Count==input.Count+2,"exactly one player load and volume call added");Check(output.Where(x=>input.Contains(x)).SequenceEqual(input),"native branches and instruction identity preserved");Check(output[0].labels.Contains("branch"),"native labels retained");Check(output.Count(x=>x.opcode==OpCodes.Call&&x.operand is MethodInfo m&&m.Name=="Volume")==1,"one scale call");
});
Run("Unexpected native foliage shapes fail explicitly",()=>{Check(transpiler!=null,"transpiler installed");try{((IEnumerable<CodeInstruction>)transpiler!.Invoke(null,[new List<CodeInstruction>{new(OpCodes.Ret)}])!).ToList();Check(false,"missing contract must fail");}catch(InvalidOperationException){}var instructions=NativeInstructions().Concat(NativeInstructions()).ToList();try{((IEnumerable<CodeInstruction>)transpiler!.Invoke(null,[instructions])!).ToList();Check(false,"ambiguous contract must fail");}catch(InvalidOperationException){}});
float Play(bool local,float source,float factor){var tree=new TreeInteractive{_lastVolume=.6f};var owner=new PlayerOwner{iPlayer=new Player{NoiseFactor=factor}};object? state=null;var prefix=Hook(foliage,"Prefix");if(prefix!=null){object?[] a=[tree,owner,null];prefix.Invoke(null,a);state=a[2];}if(!local)tree._lastVolume=source;var nativeVolume=tree._lastVolume;var volume=Hook(foliage,"Volume");if(volume!=null)nativeVolume=(float)volume.Invoke(null,[nativeVolume,owner])!;var final=Hook(foliage,"Finalizer");if(final!=null)final.Invoke(null,[tree,state,null]);return nativeVolume;}
foreach(var local in new[]{true,false})foreach(var factor in new[]{.3f,.8f,1f,1.75f,2f})Run((local?"Local":"Bot")+" foliage scales once at "+factor,()=>{var expected=(local ? .6f : .4f)*factor;Near(Play(local,.4f,factor),expected,"native branch volume scaled exactly once");Near(Play(local,.4f,factor),expected,"repeated playback does not compound");});
Run("Occluded silent foliage remains silent",()=>Near(Play(false,0,.3f),0,"native zero volume retained"));
Run("Unknown foliage actor retains native volume",()=>{var v=Hook(foliage,"Volume");Check(v!=null,"helper installed");Near((float)v!.Invoke(null,[.4f,new object()])!,.4f,"unrecognized actor unchanged");});


Run("Feather Light retains normal carried-weight penalties and the zero boundary",()=>{var(p,b,st)=MakeStamina();b.Key="BP03-2";var t=typeof(BackpackNative).Assembly.GetTypes().Single(t=>t.Name=="BackpackPhysicalWeightPatch");var method=Hook(t,"WalkLimit")!;foreach(var limit in new[]{0f,.1f,.5f,1f}){var adjusted=(float)method.Invoke(null,[limit,p.Physical])!;Near(adjusted,limit,"contents and other equipment retain normal penalties");Near(Math.Min(.25f,adjusted),Math.Min(.25f,limit),"native non-weight limits preserved");}b.Key="BP01-3";Near((float)method.Invoke(null,[.5f,p.Physical])!,.5f,"other bags unchanged");});
Run("Native weight-limit adapter preserves its one field store and labels",()=>{var type=typeof(BackpackNative).Assembly.GetTypes().Single(t=>t.Name=="BackpackPhysicalWeightPatch");var input=new List<CodeInstruction>{new(OpCodes.Ldarg_0),new(OpCodes.Ldc_R4,.5f),new(OpCodes.Stfld,typeof(PhysicalBase).GetField("WalkSpeedLimit")),new(OpCodes.Ret)};input[2].labels.Add("native-target");var output=((IEnumerable<CodeInstruction>)Hook(type,"Transpiler")!.Invoke(null,[input])!).ToArray();Check(output.Length==input.Count+2,"one corrected store");Check(output[2].labels.Contains("native-target")&&output[2].opcode==OpCodes.Ldarg_0,"branch target remains on replacement start");Check(output.Count(i=>i.opcode==OpCodes.Stfld)==1,"native assignment once");});
void Breach(Player p,Door door,EInteractionType action,bool complete){var t=typeof(BackpackNative).Assembly.GetTypes().Single(t=>t.Name=="BackpackBreachRewardPatch");object?[] before=[door,null];Hook(t,"Prefix")!.Invoke(null,before);if(complete)door.IsBroken=true;Hook(t,"Postfix")!.Invoke(null,[door,new InteractionResult{InteractionType=action},p,before[1]]);}
Run("Breach Parcel rewards only the actor's completed successful kick",()=>{var(p,b,st)=MakeStamina();b.Key="BP35-3";var d=new Door();Breach(p,d,EInteractionType.Breach,false);Check(!b.Record.Active("meleeReach"),"failed/cancelled breach grants nothing");Breach(p,d,EInteractionType.Breach,true);Check(b.Record.Active("meleeReach"),"successful actor receives buff without proximity lookup");Time.time=101;Breach(p,d,EInteractionType.Breach,true);Near(b.Record.Until["meleeReach"],120,"already broken door cannot refresh");});
Run("Opening a door and another player's breach cannot grant Breach Parcel",()=>{var(p,b,st)=MakeStamina();b.Key="BP35-3";Breach(p,new(),EInteractionType.Open,true);Check(!b.Record.Active("meleeReach"),"ordinary open excluded");Breach(new Player(),new(),EInteractionType.Breach,true);Check(!b.Record.Active("meleeReach"),"another actor excluded");});
float MedicalChange(Player p,MedEffect effect,string patch,float value,bool rollback){var previous=BackpackMedicalRestoration.Enter(effect,rollback);try{var t=typeof(BackpackNative).Assembly.GetTypes().Single(t=>t.Name==patch);object?[] args=[p.ActiveHealthController,value];Hook(t,"Prefix")!.Invoke(null,args);return(float)args[1]!;}finally{BackpackMedicalRestoration.Exit(previous);}}
foreach(var patch in new[]{"BackpackEnergyPatch","BackpackHydrationPatch"}){
 Run(patch+" reverses exactly the additional early-cancel restoration",()=>{var(p,b,e)=Medical("BP06-1",true);BackpackNative.Begin(e);var gain=MedicalChange(p,e,patch,10,false);Near(gain,15,"50% extra");var undo=MedicalChange(p,e,patch,-10,true);Near(gain+undo,0,"complete rollback");Near(MedicalChange(p,e,patch,-1,true),-1,"extra cannot be reversed twice");});
 Run(patch+" rollback survives bag removal and another active bag",()=>{var(p,b,e)=Medical("BP06-1",true);BackpackNative.Begin(e);Near(MedicalChange(p,e,patch,10,false),15,"extra granted");BackpackRuntime.States.Remove(p);Near(MedicalChange(p,e,patch,-10,true),-15,"bonus undo after removal");});
 Run(patch+" respects native resource caps when recording the bonus",()=>{var(p,b,e)=Medical("BP06-1",true);BackpackNative.Begin(e);var h=patch=="BackpackHydrationPatch"?p.ActiveHealthController.Hydration:p.ActiveHealthController.Energy;h.Current=95;Near(MedicalChange(p,e,patch,5,false),5,"no nonexistent overflow bonus");Near(MedicalChange(p,e,patch,-5,true),-5,"only granted resource undone");});
 Run(patch+" unrelated restoration during item use is not boosted",()=>{var(p,b,e)=Medical("BP06-1",true);BackpackNative.Begin(e);var t=typeof(BackpackNative).Assembly.GetTypes().Single(t=>t.Name==patch);object?[] args=[p.ActiveHealthController,10f];Hook(t,"Prefix")!.Invoke(null,args);Near((float)args[1]!,10,"no medical native-call scope");});
}
Run("Free first traversal actions cannot qualify a paid second action",()=>{var(p,b,st)=MakeStamina();Consume(st,Physical.EConsumptionType.Jump,0);Check(b.Record.Traversal=="","free first action not recorded");var before=st.Current;Consume(st,Physical.EConsumptionType.VaultLegs);Near(before-st.Current,10,"no refund earned");});
Run("Paid first traversal qualifies a different second action once",()=>{var(p,b,st)=MakeStamina();Consume(st,Physical.EConsumptionType.Jump);Time.time=101;var before=st.Current;Consume(st,Physical.EConsumptionType.VaultLegs);Near(before-st.Current,8,"different paid action discounted");before=st.Current;Consume(st,Physical.EConsumptionType.VaultLegs);Near(before-st.Current,10,"same action does not repeat refund");});
Run("Infinite stamina traversal does not count as an expenditure",()=>{var(p,b,st)=MakeStamina();st.ForceMode=true;Consume(st,Physical.EConsumptionType.Jump);Check(b.Record.Traversal=="","no paid action");st.ForceMode=false;var before=st.Current;Consume(st,Physical.EConsumptionType.VaultLegs);Near(before-st.Current,10,"next real action full cost");});
Run("Traversal eligibility expires after five seconds",()=>{var(p,b,st)=MakeStamina();Consume(st,Physical.EConsumptionType.Jump);Time.time=106;var before=st.Current;Consume(st,Physical.EConsumptionType.VaultLegs);Near(before-st.Current,10,"expired first action");});
Run("Sprint records only its first positive native leg-cost tick",()=>{var(p,b,st)=MakeStamina();var t=typeof(BackpackNative).Assembly.GetTypes().Single(t=>t.Name=="BackpackPaidSprintPatch");st.Consumptions.Add(new(){ConsumptionType=Physical.EConsumptionType.Sprint,Delta=0});void Process(){object?[] a=[st,null];Hook(t,"Prefix")!.Invoke(null,a);st.Process(.1f);Hook(t,"Postfix")!.Invoke(null,[st,.1f,a[1]]);}Process();Check(!b.SprintCostObserved&&b.Record.Traversal=="","free sprint does not qualify");Consume(st,Physical.EConsumptionType.Jump);Time.time=101;st.Consumptions[0].Delta=5;Process();Check(b.SprintCostObserved&&b.Record.Active("traversal:sprint"),"paid sprint opens refund window");Time.time=104;Process();Near(b.Record.LastTraversal,101,"continuing sprint never extends the window");Time.time=107;Check(!b.Record.Active("traversal:sprint"),"refund ends after its first five seconds");});


Run("Cold Hands status follows the actual accelerated item use after its charge is consumed",()=>{var(p,b,e)=Medical("BP14-3",false);b.ColdCharge=true;BackpackNative.Begin(e);Check(!b.ColdCharge,"real use consumes charge");var row=BackpackNative.UseStatuses(p).Single();Check(row.Active&&row.Detail=="Item use speed active"&&row.Seconds==0,"ongoing use still visible");e._interrupted=true;Check(!BackpackNative.UseStatuses(p).Any(),"cancellation hides status immediately");BackpackNative.End(e);Check(!BackpackNative.UseStatuses(p).Any(),"completion clears snapshot");});
Run("Completed conditional medical rewards report a proc only for the qualifying source",()=>{foreach(var key in new[]{"BP18-2","BP36-1"}){EffectStatusModel.ResetNotices();var(p,b,e)=Medical(key,false);TreatmentSetup(p);BackpackNative.Begin(e);Check(!EffectStatusModel.Notices(p.ProfileId,Time.time).Any(),"no proc before success");FinishTreatment(p,e);BackpackNative.End(e);var row=EffectStatusModel.Notices(p.ProfileId,Time.time).Single();Check(row.Active&&row.Detail.StartsWith("Triggered")&&row.Seconds==0,"real completed reward acknowledged");Time.time+=2;Check(!EffectStatusModel.Notices(p.ProfileId,Time.time).Any(),"instant receipt expires");}});

Console.WriteLine($"Backpack audit repairs: {cases-failures}/{cases} cases passed; {assertions} assertions; {failures} failures.");return failures==0?0:1;
public sealed class NativeInstruction {public string opcode{get;set;}="";public string? name{get;set;}public string? owner{get;set;}}
